from django.db import models
from django.contrib.auth.models import User
from datetime import datetime

class Status(models.Model):
	name=models.CharField(max_length=10, null=True, blank=True)

	def __str__(self):
		return '%s' %(self.name)

class Register(models.Model):
	lastname=models.CharField(max_length=30)
	firstname=models.CharField(max_length=30)
	nickname=models.CharField(max_length=30, null=True, blank=True)
	gender=models.CharField(max_length=30)
	address=models.CharField(max_length=100, null=True, blank=True)
	nationality=models.CharField(max_length=50, null=True, blank=True)
	birthdate=models.DateTimeField()
	spneeds=models.CharField(max_length=20, null=True, blank=True)
	accommodation=models.CharField(max_length=50, null=True, blank=True)
	allergy=models.CharField(max_length=100, null=True, blank=True)
	glastname=models.CharField(max_length=50, null=True, blank=True)
	gfirstname=models.CharField(max_length=50, null=True, blank=True)
	email_add=models.CharField(max_length=50, null=True, blank=True)
	mobile=models.CharField(max_length=30, null=True, blank=True)
	relationship=models.CharField(max_length=50, null=True, blank=True)
	parent=models.CharField(max_length=50, null=True, blank=True)
	pnumber=models.CharField(max_length=30, null=True, blank=True)
	dgroupmember=models.CharField(max_length=20, null=True, blank=True)
	pdglead=models.CharField(max_length=50, null=True, blank=True)
	cluster=models.CharField(max_length=50, null=True, blank=True)
	registered_date=models.DateTimeField(auto_now=True)
	modified_date=models.DateTimeField(auto_now=True)
#	level=models.CharField(max_length=5, null=True, blank=True)
	status=models.ForeignKey(Status, on_delete=models.CASCADE, default=1)
	k_id=models.CharField(max_length=30, null=True, blank=True)
	picture=models.CharField(max_length=50, null=True, blank=True)
	qr=models.CharField(max_length=50, null=True, blank=True)
	log=models.DateTimeField(null=True, blank=True)
	user=models.ForeignKey(User, on_delete=models.CASCADE, default=1)

	def __str__(self):
		return '%s, %s' %(self.lastname, self.firstname)
